  const fieldLabels={date:'Data',end:'Término',title:'Evento',description:'Detalhes',location:'Local',all_day:'Dia inteiro',status:'Confirmação',recurring:'Recorrente',obs:'Observações',ministro_louvor:'Ministro de louvor',execucoes_7d:'Execuções · 7 dias',erros_7d:'Erros · 7 dias',no_notion:'No acervo',pr_filipe:'Pr. Filipe',ultimo:'Último encontro',proximas:'Próximos encontros',anunciada:'Data anunciada',confirmados_desde_jul:'Confirmações registradas',saude:'Situação',ativo:'Ativo'};
