    if(!Number.isFinite(matchAt)||matchAt<0)return raw.length>220?`${raw.slice(0,217)}…`:raw;
    const start=Math.max(0,positions[matchAt]-70),end=Math.min(raw.length,(positions[matchAt]+150));
