    if(key==='pregacoes'&&value&&typeof value==='object')return `<div class="stats">${[['Mensagens no acervo',value.total],['Com resumo',value.com_resumo],['Com e-book',value.com_ebook],['Com vídeo',value.com_video]].map(([label,n])=>`<div class="stat"><strong>${esc(n??'—')}</strong><span>${label}</span></div>`).join('')}</div>${dataTable(value.ultimas,[['data','Data','date'],['titulo','Mensagem','wide'],['resumo','Resumo'],['ebook','E-book'],['url','Referência']],'Últimas mensagens no acervo')}`;
