      if(!day||day<today){const archived=Array.isArray(row)?{data:String(raw||'Data sem ano'),responsavel:row.slice(1).join(' · ')}:{...row};archived.status_historico=archived.status_historico||(!day?'data sem ano completo; mantida no histórico':'escala passada; mantida no histórico');const signature=JSON.stringify(archived);if(!history.some(item=>JSON.stringify(item)===signature))history.push(archived);continue}
