    for(const [kind,items] of [['pregacao',arr(preaching.value)],['louvor',worship]])for(const row of items){const day=parse(row.data);if(!day)continue;if(!byDay.has(day))byDay.set(day,{pregacao:[],louvor:[]});byDay.get(day)[kind].push(row)}
    const rows=[];for(const [day,group] of [...byDay].sort(([a],[b])=>a.localeCompare(b))){if(group.pregacao.length===1&&group.louvor.length===1){const p=group.pregacao[0],w=group.louvor[0];rows.push({...w,...p,data:day,ministro:w.ministro||p.ministro_louvor,obs:[p.obs,w.obs].filter(Boolean).join(' · '),conferencia:w.ministro&&p.ministro_louvor&&w.ministro!==p.ministro_louvor?`Louvor na pregação: ${p.ministro_louvor}; na escala de louvor: ${w.ministro}. Confirmar.`:'Associação por data; confirmar quando houver mais de um culto.'})}else{for(const row of group.pregacao)rows.push({...row,data:day,ministro:row.ministro_louvor,conferencia:group.pregacao.length>1||group.louvor.length>1?'Mais de uma escala nesta data; confirmar culto e horário.':'Escala de louvor não informada.'});for(const row of group.louvor)rows.push({...row,data:day,conferencia:group.pregacao.length>1||group.louvor.length>1?'Mais de uma escala nesta data; confirmar culto e horário.':'Escala de pregação não informada.'})}}
    const reception=otherScaleData(data,'escala_recepcao');for(const r of arr(reception.value?.domingos)){const day=parse(r.data);if(!day)continue;const candidates=rows.filter(row=>row.data===day);if(candidates.length===1&&!candidates[0].recepcao){candidates[0].recepcao=r.nomes;candidates[0].obs=[candidates[0].obs,r.obs].filter(Boolean).join(' · ')}else{rows.push({data:day,recepcao:r.nomes,obs:r.obs,conferencia:'Recepção separada para confirmar culto e horário.'})}}rows.sort((a,b)=>String(a.data).localeCompare(String(b.data)));
