    const hasValue=value=>Array.isArray(value)?value.some(hasValue):value!=null&&String(value).trim()!=='';
    const cols=[['data','Data','date'],['abertura','Abertura'],['pregador','Pregação'],['vocais_louvor','Vocais Louvor'],['instrumentos','Instrumentos'],['transmissao','Transmissão'],['projecao','Projeção'],['tecnicos','Técnicos'],['recepcao','Recepção'],['funcoes','Outras funções'],['obs','Observações','wide'],['divergencia_agenda','Conferência da agenda','wide'],['conferir_alteracao','Conferir alteração','wide']].filter(([key])=>key==='data'||rows.some(row=>hasValue(row[key])));
