    return `<details class="subsection scale-collapsible"><summary>🗓️ Escala dos Cultos</summary><div class="service-scroll-shell">${rows.length?controls:''}${dataTable(rows,cols,'Escala dos Cultos')}${rows.length?controls:''}</div>${pending.length?`<div class="scale-pending"><h4>Alterações aguardando conferência</h4>${dataTable(pending,[['date','Data','date'],['role','Função'],['operation','Ação'],['person','Pessoa'],['previous_person','No lugar de'],['group','Grupo'],['status','Situação'],['evidence','Evidência','wide']],'Alterações de escala pendentes')}</div>`:''}${history.length?`<details class="scale-history"><summary>Histórico arquivado por mês</summary>${renderScaleHistory(history)}</details>`:''}</details>`;
