    const overlapsDay=(event,day)=>{const start=parseTime(event.date);if(!start)return false;const end=parseTime(event.end);const lo=dayStart(day),hi=new Date(lo);hi.setDate(hi.getDate()+1);return start<hi&&(end?end>lo:start>=lo)};
